<script setup>
import { onMounted, ref } from 'vue'
import { leadTimeSettings } from '../services/leadTimeSettings.js'
const props = defineProps({ session: { type: Object, required: true } })
const form = ref(null), busy = ref(false), error = ref(''), notice = ref('')
async function load() { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { form.value = await leadTimeSettings(props.session.token) } catch (e) { error.value = e.message } finally { busy.value = false } }
async function save() { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { form.value = await leadTimeSettings(props.session.token, form.value); notice.value = 'Строки збережено. Погоджені дати замовлень не змінено.' } catch (e) { error.value = e.message } finally { busy.value = false } }
onMounted(load)
</script>
<template><section><header class="heading"><h2>Строки виконання</h2><button :disabled="busy" @click="load">Оновити</button></header><p>Робочі дні — понеділок–п’ятниця. День оформлення не враховується. Окремий календар свят не застосовується.</p><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><form v-if="form" @submit.prevent="save"><fieldset :disabled="busy"><div class="fields"><label>Мінімальний строк<input v-model.number="form.minDays" type="number" min="1" :max="form.normalDays" step="1" required></label><label>Звичайний строк до<input v-model.number="form.normalDays" type="number" :min="form.minDays" :max="form.shortageDays" step="1" required></label><label>За дефіциту матеріалів<input v-model.number="form.shortageDays" type="number" :min="form.normalDays" max="365" step="1" required></label><label>Огляд найближчих робочих днів<input v-model.number="form.upcomingDays" type="number" min="1" max="30" step="1" required></label></div><p>У формі замовлення показується діапазон від мінімального до звичайного строку. За дефіциту використовується окремий орієнтир. В огляді завдань — сьогодні та вибрана кількість наступних робочих днів.</p><p>Після зміни оновіть підказки у вже відкритій формі замовлення. Збережені дати готовності автоматично не переносяться.</p><button class="primary">Зберегти строки</button></fieldset></form></section></template>
<style scoped>.heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}fieldset{border:0;margin:0;padding:0;min-width:0}</style>
